    pub async fn do_list_collection_aliases(toc: &TableOfContent, auth: &Auth, collection_name: &str) -> Result<CollectionsAliasesResponse, StorageError> {
        let collection_pass = auth.check_collection_access(collection_name, AccessRequirements::new(), "list_collection_aliases")?;
        let access = auth.unlogged_access();
        let aliases: Vec<AliasDescription> = toc.collection_aliases(&collection_pass, access).await?
            .into_iter().map(|alias| AliasDescription { alias_name: alias, collection_name: collection_name.to_string() }).collect();
        Ok(CollectionsAliasesResponse { aliases })
    }

