    pub async fn collection_aliases(&self, collection_pass: &CollectionPass<'_>, access: &Access) -> Result<Vec<String>, StorageError> {
        let mut result = self.alias_persistence.read().await.collection_aliases(collection_pass.name());
        result.retain(|alias| access.check_collection_access(alias, AccessRequirements::new()).is_ok());
        Ok(result)
    }

